import path from "path";

/**
 * Upload path helpers shared by the visit, vault-item and expense media routes.
 *
 * Rules:
 * - Stored filenames are generated by the server: `<uuid>.<ext>`, where `<ext>`
 *   comes from the allowlist below, never from the client filename.
 * - Client filenames are only ever stored as display text (`original_name`),
 *   after `sanitizeDisplayName`.
 * - Every path that is read, written or deleted goes through `resolveStoredUpload`,
 *   which rejects separators, dot segments, NUL bytes and anything that does not
 *   resolve strictly beneath the upload root.
 */

export const UPLOAD_ROOT = "/app/uploads";

const IMAGE_EXTENSION_BY_MIME = new Map<string, string>([
  ["image/jpeg", "jpg"],
  ["image/png", "png"],
  ["image/webp", "webp"],
  ["image/gif", "gif"],
  ["image/heic", "heic"],
  ["image/heif", "heif"],
]);

/** Extension to store for an allowed image MIME type, or null when the type is not allowed. */
export function imageExtensionForMime(mime: string): string | null {
  return IMAGE_EXTENSION_BY_MIME.get(mime) ?? null;
}

/** An id or directory segment: letters, digits, hyphen, underscore only. */
const SAFE_SEGMENT = /^[A-Za-z0-9_-]{1,128}$/;

/**
 * A stored filename: a safe base name and a short alphanumeric extension.
 * Legacy rows may carry an extension that was taken from a client filename, so the
 * read path accepts any alphanumeric extension here; the containment check still applies.
 */
const STORED_FILENAME = /^[A-Za-z0-9_-]{1,128}\.[A-Za-z0-9]{1,8}$/;

export function isSafePathSegment(value: string): boolean {
  return SAFE_SEGMENT.test(value);
}

export function isStoredFilename(value: string): boolean {
  return STORED_FILENAME.test(value);
}

/**
 * Resolve `ownerId` and `filename` under `root` and confirm the result stays inside `root`.
 * Returns null for any value that could escape the directory, or that is not a stored-file shape.
 */
export function resolveStoredUpload(root: string, ownerId: string, filename: string): string | null {
  if (!isSafePathSegment(ownerId) || !isStoredFilename(filename)) return null;
  const base = path.resolve(root);
  const resolved = path.resolve(base, ownerId, filename);
  if (!resolved.startsWith(base + path.sep)) return null;
  return resolved;
}

/** Strip client-supplied path parts and control characters from a display filename. */
export function sanitizeDisplayName(raw: string | null | undefined, fallback = "upload"): string {
  if (!raw) return fallback;
  // Keep only the last component, whichever separator the client used.
  const last = raw.split(/[\\/]/).pop() ?? "";
  const cleaned = last
    .replace(/[\u0000-\u001f\u007f]/g, "")
    .trim()
    .replace(/^\.+/, "")
    .slice(0, 255)
    .trim();
  return cleaned || fallback;
}
